CREATE TABLE IF NOT EXISTS employees(id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,first_name TEXT NOT NULL,last_name TEXT NOT NULL,email TEXT NOT NULL,phone TEXT NOT NULL,address TEXT,city TEXT,state TEXT,zip_code TEXT,acknowledged BOOLEAN NOT NULL CHECK(acknowledged),employee_name TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE UNIQUE INDEX IF NOT EXISTS employees_email_lower_key ON employees(lower(email));
CREATE TABLE IF NOT EXISTS employment(employee_id BIGINT PRIMARY KEY REFERENCES employees(id),department TEXT NOT NULL,job_title TEXT NOT NULL,start_date DATE NOT NULL,employment_type TEXT NOT NULL,annual_salary NUMERIC(12,2) NOT NULL CHECK(annual_salary>0),remote_employee BOOLEAN NOT NULL,remote_location TEXT,CHECK(NOT remote_employee OR NULLIF(TRIM(remote_location),'') IS NOT NULL));
CREATE TABLE IF NOT EXISTS benefits(employee_id BIGINT PRIMARY KEY REFERENCES employees(id),health_plan TEXT NOT NULL,dental BOOLEAN NOT NULL,vision BOOLEAN NOT NULL,retirement_percent NUMERIC(5,2) NOT NULL CHECK(retirement_percent BETWEEN 0 AND 100));
CREATE TABLE IF NOT EXISTS emergency_contacts(employee_id BIGINT PRIMARY KEY REFERENCES employees(id),contact_name TEXT NOT NULL,relationship TEXT NOT NULL,phone TEXT NOT NULL,notes TEXT);
